  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md classifies T-001–T-004 high for execution-proof contracts, trusted workflow integration, model capability/access constraints and protected launch boundaries. T-005 is medium with changes limited to verified activation references, documentation and release metadata; algorithm repairs explicitly return to their owning scope."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "T-001–T-004 each explicitly require failing tests committed before implementation, captured Red→Green evidence and a named independent reviewer verdict in Done When. No task declares critical risk."
    },
    {
      "id": "TASK-SIZE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-004 Planned Files and Done When combine more than three distinct implementation areas: renderer/installer and generated host definitions; paired launch validators, panelists and run-record emission; diagnosis/domain/auditor and self-improvement entry points; freshness workflow/notification maintenance; and actual candidate-versus-baseline adoption evaluations with two repetitions per case. The first four Done When bullets bundle migration, native integration and behavioral promotion into one session-sized task. This makes independent completion and verification too coarse and risks incomplete caller migration or deferred adoption evidence. Split into ordered, independently verifiable integration, maintenance and adoption tasks while preserving paired-validator atomicity."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Functional model work has explicit negatives: T-003 maps to AC-012 partial/stale discovery, AC-014 malformed/conflicting configuration and AC-016 unavailable/mismatched identity; T-004 maps to AC-017 fetch failure/untrusted sources and AC-018 comment-only mutation/identity reservation. CI tasks additionally cover malformed plans, missing receipts and corrupt caches. T-005 retains unproven categories full and records unavailable external validation rather than claiming success."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "No standalone test-only task is declared. Embedded validation matches scope: T-001 uses unit/integration fixtures for planner/interpreter/aggregate boundaries; T-002 uses workflow integration; T-004 uses launcher/renderer/installer integration. The Test Ownership table links acceptance validation explicitly to AC-001–AC-020, and T-005 distinguishes hosted acceptance from fixtures."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "Every high-risk task T-001–T-004 requires documented and tested rollback in a disposable checkout with before/after hashes and baseline results. Shared rollback specifies force-full for CI and a validated explicit model pin or prior tested release, without rewriting evidence or identity ledgers."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md Shared file ordering and rollback assigns distinct catalog purposes to T-001–T-005 and limits T-004 policy edits to adoption metadata. The sequential Blockers chain orders shared catalog, workflow-interpreter and test-file edits; no uncoordinated parallel ownership is declared."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-002 consumes T-001 planner/aggregate contracts and baseline inventory; T-003 adds suite/dependency entries to the integrated CI catalog after T-002; T-004 consumes T-003 immutable selection and host helper; T-005 validates and releases the integrated implementation. requirements.md additionally explicitly orders CI before model work and shared release last. Round 1: no prior summary; the supplied current-round summary contains only check IDs and counts."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "SKIP",
      "severity": "Major",
      "finding": "SKIP: no bugfix or debugging task in scope."
    }
  ],
  "findings": [
    {
      "check_id": "TASK-SIZE",
      "severity": "Major",
      "task_id": "T-004",
      "finding": "specs/ci-model-modernization/tasks.md, T-004 Planned Files and Done When bullets 1–4, combine renderer/installer migration, paired launch/evidence integration, additional managed-role and automation entry points, freshness maintenance, and repeated actual candidate adoption evaluations. This exceeds a single focused implementation session and leaves caller migration and behavioral promotion behind one coarse completion gate, risking incomplete migration or deferred evidence. Split into ordered, independently verifiable tasks, keeping each launcher/validator pair together and adoption dependent on verified integration."
    }
  ]
